import fs from "node:fs";
import path from "node:path";
import os from "node:os";

const B64_CHAT_LAB = "";
const B64_CHAT_UI  = "";
const B64_RES_LAB  = "";
const B64_RES_UI   = "";

const FILES = {
  "general-chat-lab.mjs": B64_CHAT_LAB,
  "src/general-chat-lab.mjs": B64_CHAT_LAB,
  "research-lab.mjs": B64_RES_LAB,
  "src/research-lab.mjs": B64_RES_LAB,
  "public/general-chat-ui.js": B64_CHAT_UI,
  "general-chat-ui.js": B64_CHAT_UI,
  "public/verified-research-ui.js": B64_RES_UI,
  "verified-research-ui.js": B64_RES_UI
};

console.log("\n==================================================================");
console.log("🚀 PIXELMORPHIC AI v46.0 — ROOT + STUDIO-TOOLS MASTER INSTALLER");
console.log("   • Fixes public/studio-tools.js & Root general-chat-lab.mjs");
console.log("   • 🧮 Sci-Calc & Symbols Keypad Drawer (Dual Calculator + Search)");
console.log("   • 🗂️ Interactive 3D Study Flashcards & 📊 Study Infographics");
console.log("   • Hidden General Chat/Study Sources + Google Vector Mic Icon");
console.log("==================================================================\n");

function stripLegacyInjectedUiFromStudioTools(code) {
  let out = String(code || "");
  const cutMarkers = [
    "/* === MORPHIC_RESEARCH_UI_START === */",
    "/* === MORPHIC_GENERAL_CHAT_UI_START === */",
    "/* === MORPHIC RESEARCH",
    "/* === PIXELMORPHIC RESEARCH",
    "/* === PIXELMORPHIC RESEARCH LAB V4",
    "/* Pixelmorphic Research Lab",
    "/* Pixelmorphic AI Research Lab",
    "/* ============================================================================\n * PIXELMORPHIC AI",
    "/* ============================================================================\r\n * PIXELMORPHIC AI",
    "// ============================================================================\n// PIXELMORPHIC AI",
    "// ============================================================================\r\n// PIXELMORPHIC AI",
    "window.__cleanResearch",
    "window.__researchLab",
    "window.__emeraldResearch",
    "window.__pmResearchSafeV4",
    "window.__morphicResearch",
    "window.__verifiedResearch",
    "window.__morphicGeneralChat"
  ];

  let earliestIdx = -1;
  for (const m of cutMarkers) {
    const idx = out.indexOf(m);
    if (idx !== -1) {
      let cutPos = idx;
      if (m.startsWith("window.__")) {
        const iifePos = out.lastIndexOf("(function", idx);
        if (iifePos !== -1 && idx - iifePos < 500) cutPos = iifePos;
      }
      if (earliestIdx === -1 || cutPos < earliestIdx) earliestIdx = cutPos;
    }
  }
  if (earliestIdx !== -1) {
    out = out.slice(0, earliestIdx);
  }
  return out.trimEnd();
}

const candidateRoots = new Set();
const cwd = process.cwd();
const parentDir = path.resolve(cwd, "..");
const grandParentDir = path.resolve(cwd, "../..");

for (const dir of [cwd, parentDir, grandParentDir]) {
  if (fs.existsSync(path.join(dir, "server.mjs")) || fs.existsSync(path.join(dir, "package.json")) || fs.existsSync(path.join(dir, "public"))) {
    candidateRoots.add(dir);
  }
}

const downloadsDir = path.join(os.homedir(), "Downloads");
const knownPaths = [
  path.join(downloadsDir, "Pixelmorphic_Samurai_Integration (2)", "pixelmorphic-samurai"),
  path.join(downloadsDir, "Pixelmorphic_Samurai_Integration", "pixelmorphic-samurai"),
  path.join(downloadsDir, "pixelmorphic-samurai"),
  "C:\\Users\\harsh\\Downloads\\Pixelmorphic_Samurai_Integration (2)\\pixelmorphic-samurai"
];
for (const kp of knownPaths) {
  if (fs.existsSync(kp)) candidateRoots.add(path.resolve(kp));
}

if (fs.existsSync(downloadsDir)) {
  try {
    for (const entry of fs.readdirSync(downloadsDir, { withFileTypes: true })) {
      if (!entry.isDirectory()) continue;
      const p1 = path.join(downloadsDir, entry.name);
      if (fs.existsSync(path.join(p1, "server.mjs")) && fs.existsSync(path.join(p1, "public"))) {
        candidateRoots.add(path.resolve(p1));
      }
      try {
        for (const sub of fs.readdirSync(p1, { withFileTypes: true })) {
          if (!sub.isDirectory()) continue;
          const p2 = path.join(p1, sub.name);
          if (fs.existsSync(path.join(p2, "server.mjs")) && fs.existsSync(path.join(p2, "public"))) {
            candidateRoots.add(path.resolve(p2));
          }
        }
      } catch (_) {}
    }
  } catch (_) {}
}

if (candidateRoots.size === 0) {
  candidateRoots.add(cwd);
}

const chatUiText = Buffer.from(B64_CHAT_UI, "base64").toString("utf8");
const resUiText  = Buffer.from(B64_RES_UI, "base64").toString("utf8");

for (const rootDir of candidateRoots) {
  if (path.basename(rootDir).toLowerCase().startsWith("pixelmorphic_") && !fs.existsSync(path.join(rootDir, "server.mjs")) && candidateRoots.size > 1) {
    continue;
  }
  console.log("📂 Updating Project Root:", rootDir);

  // 1. Write all 8 root + src/ + public/ files so both root imports and src/ imports get v46.0!
  for (const [relPath, b64] of Object.entries(FILES)) {
    const fullPath = path.join(rootDir, relPath);
    fs.mkdirSync(path.dirname(fullPath), { recursive: true });
    fs.writeFileSync(fullPath, Buffer.from(b64, "base64"));
    console.log("   ✅ Wrote:", relPath, "(" + fs.statSync(fullPath).size + " bytes)");
  }

  // 2. Clean public/studio-tools.js of stale v40 code AND embed fresh v46.0 UI!
  const studioPath = path.join(rootDir, "public", "studio-tools.js");
  if (fs.existsSync(studioPath)) {
    const rawStudio = fs.readFileSync(studioPath, "utf8");
    const cleanHostStudio = stripLegacyInjectedUiFromStudioTools(rawStudio);
    const updatedStudio = cleanHostStudio
      + "\n\n/* === MORPHIC_RESEARCH_UI_START === */\n"
      + resUiText
      + "\n/* === MORPHIC_RESEARCH_UI_END === */\n\n"
      + "/* === MORPHIC_GENERAL_CHAT_UI_START === */\n"
      + chatUiText
      + "\n/* === MORPHIC_GENERAL_CHAT_UI_END === */\n";
    fs.writeFileSync(studioPath, updatedStudio, "utf8");
    console.log("   ✅ Replaced stale v40 UI inside public/studio-tools.js with v46.0!");
  }

  // 3. Update public/index.html cache-busting query strings
  const indexHtmlPath = path.join(rootDir, "public", "index.html");
  if (fs.existsSync(indexHtmlPath)) {
    let html = fs.readFileSync(indexHtmlPath, "utf8");
    const stamp = "46_" + Date.now();
    html = html.replace(/studio-tools\.js(\?v=[^"\x27\s>]*)?/g, "studio-tools.js?v=" + stamp);
    html = html.replace(/general-chat-ui\.js(\?v=[^"\x27\s>]*)?/g, "general-chat-ui.js?v=" + stamp);
    html = html.replace(/verified-research-ui\.js(\?v=[^"\x27\s>]*)?/g, "verified-research-ui.js?v=" + stamp);
    if (!html.includes("general-chat-ui.js")) {
      html = html.replace("</body>", `  <script src="/general-chat-ui.js?v=${stamp}"></script>\n</body>`);
    }
    fs.writeFileSync(indexHtmlPath, html, "utf8");
    console.log("   ✅ Cache-busted scripts (?v=" + stamp + ") in public/index.html!");
  }

  // 4. Ensure server.mjs imports ./research-lab.mjs and ./general-chat-lab.mjs
  const serverPath = path.join(rootDir, "server.mjs");
  if (fs.existsSync(serverPath)) {
    let srv = fs.readFileSync(serverPath, "utf8");
    if (!srv.includes("./general-chat-lab.mjs")) {
      srv = "import \"./general-chat-lab.mjs\";\n" + srv;
    }
    if (!srv.includes("./research-lab.mjs")) {
      srv = "import \"./research-lab.mjs\";\n" + srv;
    }
    fs.writeFileSync(serverPath, srv, "utf8");
    console.log("   ✅ Verified root imports in server.mjs!");
  }

  // 5. Scrub any old sources from data/morphic-user-storage.json
  const storageFile = path.join(rootDir, "data", "morphic-user-storage.json");
  if (fs.existsSync(storageFile)) {
    try {
      const raw = JSON.parse(fs.readFileSync(storageFile, "utf8"));
      if (raw && typeof raw === "object") {
        for (const k of Object.keys(raw)) {
          if (k.includes("chat_threads") && typeof raw[k] === "string") {
            const parsed = JSON.parse(raw[k]);
            if (Array.isArray(parsed)) {
              parsed.forEach((t) => {
                if (Array.isArray(t.messages)) {
                  t.messages.forEach((m) => { if (m && m.sources) m.sources = []; });
                }
              });
              raw[k] = JSON.stringify(parsed);
            }
          }
        }
        fs.writeFileSync(storageFile, JSON.stringify(raw, null, 2), "utf8");
      }
    } catch (_) {}
  }
}

console.log("\n🎉 PIXELMORPHIC v46.0 INSTALLED SUCCESSFULLY!");
console.log("👉 Now run: npm.cmd start  and press Ctrl + Shift + R in your browser!\n");
